class ATM {
    long[] stock=new long[5];
    int[] values={
        20,50,100,200,500
    };
    public ATM(){
    }
    public void deposit(int[] banknotesCount){
        for(int i=0;i<5;i++)stock[i]+=banknotesCount[i];
    }
    public int[] withdraw(int amount){
        int[] take=new int[5];
        int remaining=amount;
        for(int i=4;i>=0;i--){
            take[i]=(int)Math.min(stock[i],remaining/values[i]);
            remaining-=take[i]*values[i];
        }
        if(remaining!=0)return new int[]{
            -1
        };
        for(int i=0;i<5;i++)stock[i]-=take[i];
        return take;
    }
}

code.kotlin:
class ATM {
    private val stock=LongArray(5);
    private val values=intArrayOf(20,50,100,200,500);
    fun deposit(banknotesCount:IntArray){
        for(i in 0..4)stock[i]+=banknotesCount[i]
    };
    fun withdraw(amount:Int):IntArray{
        val take=IntArray(5);
        var remaining=amount;
        for(i in 4 downTo 0){
            take[i]=minOf(stock[i],(remaining/values[i]).toLong()).toInt();
            remaining-=take[i]*values[i]
        };
        if(remaining!=0)return intArrayOf(-1);
        for(i in 0..4)stock[i]-=take[i];
        return take
    }
}

